mapper.select:
SELECT r.id AS receivableId, r.receivable_no AS receivableNo, r.order_id AS orderId, r.customer_id AS customerId, r.settlement_customer_id AS settlementCustomerId, r.customer_name_snapshot AS customerNameSnapshot, r.entry_type AS entryType, r.amount, so.seller_id AS sellerId FROM finance_receivable r LEFT JOIN sales_order so ON so.id = r.order_id AND so.deleted = FALSE WHERE r.id IN
#{targetId}
AND r.entry_type = 'NORMAL' AND r.deleted = FALSE ORDER BY r.id FOR UPDATE OF r



    r.deleted = FALSE
    AND r.event_at >= #{timeRange.startAt}
    AND r.event_at < #{timeRange.endAt}

        AND FALSE


            AND so.seller_id IN
            #{sellerId}


    AND r.id = #{query.receivableId}
    AND r.customer_id = #{query.customerId}

        AND so.order_no ILIKE CONCAT('%', #{query.orderNo}, '%')


        AND r.entry_type = #{query.entryType}


        AND r.entry_type = 'NORMAL'
        AND CASE WHEN written.writtenOffAmount = 0 THEN 'OPEN'
                 WHEN GREATEST(r.amount - red.redAmount - written.writtenOffAmount, 0) = 0
                      AND GREATEST(written.writtenOffAmount - (r.amount - red.redAmount), 0) = 0 THEN 'SETTLED'
                 ELSE 'PARTIAL' END = #{query.settleState}


ORDER BY r.event_at DESC, r.id DESC
